# -*- coding: utf-8 -*-
# (speaker, italiano, coreano); speaker None => didascalia, "#" => titolo di scena (nessuno dei due conta come battuta)
G, GI, K, H, PM, R = "Graziella", "Giulia", "Kim", "Han", "Mancini", "Renzo"
D = [
("#", "Scena 1 — Domenica 24 agosto, ore 8. Lo studio di Paolo, casa Corsini.", "장면 1 — 8월 24일 일요일 아침 8시. 코르시니 가, 파올로의 서재."),
(None, "Le persiane sono socchiuse per il caldo. Sulla scrivania di Paolo, due fogli uno accanto all'altro: a sinistra la lettera della Maison Varenne, su carta pesante con il logo in rilievo; a destra una mail stampata da Seul. Giulia sistema il portatile davanti alla nonna.", "더위 때문에 덧창이 반쯤 닫혀 있다. 파올로의 책상 위에 종이 두 장이 나란히 놓여 있다. 왼쪽은 로고가 양각된 두꺼운 종이에 쓴 메종 바렌의 편지, 오른쪽은 서울에서 온 메일을 출력한 것. 줄리아가 할머니 앞에 노트북을 놓아 준다."),
(GI, "Nonna, la telecamera è questa lucina verde. Se la vedi accesa, ti vedono.", "할머니, 카메라는 이 초록 불빛이야. 이게 켜져 있으면 저쪽에서 할머니가 보여."),
(G, "E se la copro con un dito?", "손가락으로 가리면?"),
(GI, "Ti vedono il dito. Dai, nonna. A Seul sono le tre del pomeriggio, ti stanno aspettando.", "손가락이 보이지. 자, 할머니. 서울은 오후 3시야, 다들 기다리고 있어."),
(G, "Le tre del pomeriggio di domenica. E io li ricevo in vestaglia.", "일요일 오후 3시라. 그런데 나는 잠옷 가운 차림으로 맞는구나."),
(GI, "Non sei in vestaglia. Ti sei messa la collana di perle.", "가운 아니잖아. 진주 목걸이까지 했으면서."),
(G, "Appunto. Per la Corea, le perle. Per Parigi ci penserò.", "그러니까. 한국엔 진주. 파리는 생각해 보고."),
(None, "Sullo schermo compaiono due volti: Kim Seo-yeon, in un ufficio luminoso, e accanto a lei un uomo sui cinquant'anni, cravatta grigia, capelli corti. Il direttore Han Jae-min.", "화면에 두 얼굴이 나타난다. 환한 사무실의 김서연, 그리고 그 옆에 회색 넥타이에 머리를 짧게 깎은 쉰 살쯤의 남자. 한재민 상무다."),
(K, "Buongiorno, signora Corsini. Grazie di averci ricevuto di domenica.", "안녕하세요, 코르시니 여사님. 일요일에 만나 주셔서 감사합니다."),
(G, "Buongiorno a Lei, signora Kim. Da noi è mattina, da voi è già pomeriggio. Siete sempre in anticipo sulla vita, voi.", "안녕하세요, 김 차장님. 여긴 아침인데 그쪽은 벌써 오후네요. 그쪽 분들은 늘 인생을 앞서가는군요."),
(K, "Solo di sette ore. Le presento il direttore Han Jae-min. Ha firmato con i Suoi figli a maggio.", "일곱 시간만요. 한재민 상무님을 소개해 드릴게요. 5월에 아드님 따님들과 계약서에 서명하신 분이에요."),
(H, "Buongiorno, signora. È un onore. Mi scusi se il mio italiano è un po' arrugginito: la Bocconi è lontana.", "안녕하십니까, 여사님. 영광입니다. 제 이탈리아어가 좀 녹슬었더라도 양해해 주십시오. 보코니 시절이 오래돼서요."),
(G, "Il Suo italiano è migliore di quello di mia nipote quando scrive i messaggi. Prego, direttore. Mi dica.", "상무님 이탈리아어는 우리 손녀가 문자 보낼 때보다 낫습니다. 말씀하세요, 상무님."),
(H, "Sarò breve. Il gruppo Gaon vorrebbe entrare nel capitale della Pelletteria Corsini. Con il quindici per cento.", "짧게 말씀드리겠습니다. 가온 그룹은 펠레테리아 코르시니의 자본에 참여하고 싶습니다. 15퍼센트로요."),
(G, "Il quindici. E in cambio?", "15퍼센트. 그 대가로는요?"),
(H, "In cambio portiamo due milioni e quattrocentomila euro, tutti in aumento di capitale. Soldi che entrano nell'azienda, non nelle tasche di qualcuno.", "그 대가로 240만 유로를 드립니다. 전액 증자로요. 누군가의 주머니가 아니라 회사로 들어가는 돈입니다."),
(G, "Lo apprezzo. Ma i soldi non arrivano mai da soli. Che cosa chiedete, oltre al quindici per cento?", "고맙군요. 하지만 돈은 절대 혼자 오지 않지요. 15퍼센트 말고 무엇을 원하시나요?"),
(H, "Due cose. Un osservatore nel consiglio, senza diritto di voto. E un diritto di prima offerta sulla distribuzione in Asia, per cinque anni.", "두 가지입니다. 의결권 없는 이사회 옵서버 한 자리. 그리고 5년간 아시아 유통에 대한 우선 제안권입니다."),
(G, "Diritto di prima offerta. Me lo spieghi come a una casalinga di Scandicci. Perché lo sono.", "우선 제안권이라. 스칸디치의 가정주부한테 하듯 설명해 주세요. 저는 그러니까요."),
(H, "Se domani un distributore di Tokyo o di Shanghai vuole le vostre borse, voi lo dite prima a noi. Se noi facciamo un'offerta uguale, il lavoro è nostro. Se no, siete liberi.", "내일 도쿄나 상하이의 유통업자가 여러분 가방을 원하면, 먼저 저희에게 알려 주시는 겁니다. 저희가 같은 조건을 내면 그 일은 저희 몫이고, 아니면 자유롭게 하시면 됩니다."),
(G, "E il signor Watanabe? Ha le nostre borse in negozio da luglio. Ormai è quasi di famiglia.", "와타나베 씨는요? 7월부터 우리 가방을 매장에 두고 있어요. 이젠 거의 가족이나 마찬가지인데."),
(K, "Il signor Watanabe resta. L'abbiamo scritto apposta: i contratti già firmati non si toccano.", "와타나베 씨는 그대로예요. 일부러 써 넣었어요. 이미 서명한 계약은 건드리지 않는다고요."),
(G, "Signora Kim, Lei è molto gentile. Ma mi dica una cosa, da donna a donna: perché adesso?", "김 차장님, 참 친절하시네요. 그런데 여자 대 여자로 하나만 말해 줘요. 왜 하필 지금이죠?"),
(K, "(una pausa) Perché la settimana scorsa qualcuno a Parigi ha fatto un'offerta. Le notizie viaggiano, signora. Anche nel nostro settore.", "(잠시 말을 멈췄다가) 지난주에 파리에서 누가 제안을 했으니까요. 소식은 퍼지거든요, 여사님. 우리 업계에서도요."),
(G, "Viaggiano più veloci degli aerei.", "비행기보다 빨리 퍼지죠."),
(H, "Noi non vogliamo comprare la vostra famiglia, signora. Vogliamo che la vostra famiglia cresca in Asia. Con il vostro nome, non con il nostro.", "저희는 여사님 가족을 사려는 게 아닙니다. 여사님 가족이 아시아에서 자라길 바라는 겁니다. 저희 이름이 아니라 여러분 이름으로요."),
(G, "È una bella frase. L'ha preparata?", "멋진 말이네요. 준비해 오신 건가요?"),
(H, "(sorride) Ieri sera. Ma è vera lo stesso.", "(미소 지으며) 어젯밤에요. 그래도 진심입니다."),
(G, "Le frasi preparate a volte sono le più vere. Mio marito preparava perfino i buongiorno. Quanto tempo ci date?", "준비한 말이 때로는 제일 진실하지요. 제 남편은 아침 인사까지 준비했어요. 시간은 얼마나 주실 건가요?"),
(H, "Fino alla fine di settembre. Non di più.", "9월 말까지입니다. 그 이상은 어렵습니다."),
(K, "E signora... comunque decidiate, il contratto dei grandi magazzini resta. Due anni sono due anni.", "그리고 여사님… 어떻게 결정하시든 백화점 계약은 그대로예요. 2년은 2년이니까요."),
(G, "Grazie, Seo-yeon. Posso chiamarla così? Mia figlia la chiama in un altro modo.", "고마워요, 서연 씨. 그렇게 불러도 될까요? 우리 딸은 다른 호칭으로 부르던데."),
(K, "«Eonni». Sì, lo so. Mi chiami come preferisce, signora.", "'언니'요. 네, 알아요. 편하신 대로 불러 주세요, 여사님."),
(G, "Allora Seo-yeon. E direttore: ci penserò. Da noi si decide a tavola. E la tavola, questa settimana, sarà lunga.", "그럼 서연 씨. 그리고 상무님, 생각해 보겠습니다. 우리 집은 식탁에서 결정해요. 그리고 이번 주 식탁은 길어질 겁니다."),
(None, "Lo schermo diventa nero. Giulia richiude il portatile piano, come se dentro dormisse qualcuno.", "화면이 꺼진다. 줄리아가 안에서 누가 자고 있기라도 한 듯 노트북을 살며시 닫는다."),
(GI, "Nonna. E Parigi quanto vi dà?", "할머니. 그럼 파리는 얼마를 주는데?"),
(G, "Parigi offre di più. Molto di più. Ed è proprio questo che mi fa paura.", "파리가 더 많이 줘. 훨씬 더. 그런데 바로 그게 무서운 거야."),
(GI, "Perché?", "왜?"),
(G, "Perché chi paga molto, di solito, vuole molto. Vai a fare colazione, va'. Fra poco arriva l'avvocato.", "많이 주는 사람은 대개 많이 원하거든. 가서 아침 먹어라, 어서. 곧 변호사님 오신다."),

("#", "Scena 2 — Ore 10.30. La cucina.", "장면 2 — 오전 10시 30분. 부엌."),
(None, "L'avvocato Mancini arriva dalla messa, con la giacca sul braccio e il cappello di paglia. Graziella ha preparato il caffè nella moka grande e un piatto di schiacciata all'uva.", "만치니 변호사가 미사를 마치고 재킷을 팔에 걸친 채 밀짚모자를 쓰고 온다. 그라치엘라는 큰 모카 포트에 커피를 내리고 포도 스키아차타 한 접시를 준비해 두었다."),
(PM, "Buongiorno, signora. Schiacciata all'uva ad agosto? È presto.", "안녕하세요, 여사님. 8월에 포도 스키아차타요? 이르네요."),
(G, "È l'uva di Renzo, quella del pergolato. Matura prima di tutte le altre, come lui. Si sieda, avvocato.", "렌초네 포도덩굴에서 딴 거예요. 렌초처럼 다른 포도보다 먼저 익죠. 앉으세요, 변호사님."),
(PM, "Ho letto tutto ieri sera. Due volte la lettera di Parigi, una volta la mail di Seul.", "어젯밤에 다 읽었습니다. 파리 편지는 두 번, 서울 메일은 한 번."),
(G, "Due volte Parigi. Allora è più complicata.", "파리를 두 번이라. 그럼 그쪽이 더 복잡하군요."),
(PM, "È più lunga. E più lunga, di solito, vuol dire più complicata. Vuole i numeri o vuole il senso?", "더 깁니다. 그리고 대개 길면 복잡하지요. 숫자를 원하세요, 요지를 원하세요?"),
(G, "Prima il senso. I numeri li ha Filippo, e quando li legge lui suonano meglio.", "요지부터요. 숫자는 필리포가 갖고 있고, 그 애가 읽으면 더 그럴듯하게 들리거든요."),
(PM, "Il senso è questo. La Maison compra il quaranta per cento. Metà con un aumento di capitale, metà comprando quote da voi, in proporzione. Valuta l'intera azienda diciotto milioni.", "요지는 이렇습니다. 메종이 지분 40퍼센트를 삽니다. 절반은 증자로, 절반은 여러분에게서 지분을 비율대로 사들여서요. 회사 전체 가치를 1,800만 유로로 봅니다."),
(G, "Diciotto. E Seul?", "1,800만. 서울은요?"),
(PM, "Seul, con due milioni e quattro per il quindici, la valuta intorno ai sedici. Parigi paga un po' di più per ogni punto. Ma compra molti più punti.", "서울은 15퍼센트에 240만이니 1,600만 정도로 보는 셈이죠. 파리가 1퍼센트당 조금 더 줍니다. 하지만 훨씬 많은 지분을 사지요."),
(G, "Quaranta su cento. Con il quaranta, chi comanda?", "100 중에 40. 40이면 누가 주인이에요?"),
(PM, "Sulla carta, ancora voi. Ma leggiamo l'articolo quattro. La Maison avrebbe due consiglieri su cinque. E un diritto di veto su, cito, «qualsiasi attività del marchio Corsini Scandicci al di fuori del territorio italiano».", "서류상으로는 여전히 여러분입니다. 하지만 4조를 읽어 보지요. 메종은 이사 다섯 중 두 자리를 갖습니다. 그리고 인용하자면 '이탈리아 영토 밖에서의 Corsini Scandicci 브랜드의 모든 활동'에 대한 거부권을 갖습니다."),
(G, "Fuori dall'Italia. Cioè Seul, Tokyo, Amsterdam.", "이탈리아 밖이라. 그러니까 서울, 도쿄, 암스테르담."),
(PM, "Cioè tutto quello che i Suoi figli hanno costruito da gennaio. I contratti in corso arriverebbero alla scadenza. Poi, niente rinnovi.", "그러니까 자제분들이 1월부터 쌓아 온 전부지요. 진행 중인 계약은 만기까지만 갑니다. 그 뒤엔 갱신이 없고요."),
(G, "E in cambio?", "그 대가로는요?"),
(PM, "In cambio, cinque anni di volumi garantiti. Non meno di ventiquattro milioni di ordini all'anno, ai prezzi di oggi. È più di quanto vi danno adesso.", "그 대가로 5년간 물량을 보장합니다. 지금 가격으로 연 2,400만 유로 이상의 주문이요. 지금 받는 것보다 많습니다."),
(G, "Duecentocinquanta stipendi per cinque anni.", "5년 동안 월급 250명분이네요."),
(PM, "Duecentocinquanta stipendi per cinque anni. È questo che Filippo vedrà per primo. E non avrà torto.", "5년 동안 월급 250명분. 필리포가 제일 먼저 보는 게 그거겠지요. 그리고 틀린 생각도 아니고요."),
(G, "Filippo non ha mai torto sui numeri. Ha torto sul tempo: crede che cinque anni siano tanti.", "필리포는 숫자에선 틀리는 법이 없어요. 시간에서 틀리죠. 5년이 길다고 믿거든요."),
(PM, "Per un'azienda sono pochi. Per un uomo di quarantaquattro anni con una figlia di sedici, sono tantissimi.", "회사에겐 짧지요. 하지만 열여섯 살 딸을 둔 마흔네 살 남자에겐 아주 긴 시간입니다."),
(G, "Lei difende sempre Filippo, avvocato.", "변호사님은 늘 필리포 편이시네요."),
(PM, "Difendo chi rischia di restare solo, signora. In questa storia, è lui.", "저는 혼자 남을 위험이 있는 사람 편입니다, 여사님. 이 이야기에선 그게 필리포고요."),
(G, "E le regole? Quelle che ha scritto a gennaio e che tengo nel cassetto.", "그럼 규칙은요? 1월에 변호사님이 써 주셔서 제 서랍에 넣어 둔 그것 말이에요."),
(PM, "Le regole sono chiare. Per una decisione così servono le firme dei tre ragazzi e la Sua approvazione. Se uno si rifiuta, passati trenta giorni, decide Lei.", "규칙은 명확합니다. 이런 결정엔 세 자녀의 서명과 여사님의 승인이 필요합니다. 한 명이 거부하면 30일이 지난 뒤 여사님이 결정하시고요."),
(G, "Trenta giorni. La Maison ci dà tempo fino al quindici settembre. Seul fino alla fine del mese.", "30일. 메종은 9월 15일까지 시간을 줬어요. 서울은 월말까지고요."),
(PM, "Allora le date le hanno scelte loro, non Lei. Ed è la prima cosa che Le consiglio di cambiare.", "그럼 날짜는 여사님이 아니라 그쪽이 정한 셈이군요. 그게 제가 제일 먼저 바꾸시라고 권하는 겁니다."),
(G, "Tanto vale chiedere a tutti e due di aspettare, allora.", "그럼 차라리 두 쪽 다 기다려 달라고 하는 게 낫겠네요."),
(PM, "Tanto vale. Chi ha davvero bisogno di voi aspetta. Chi non aspetta, forse, cercava qualcos'altro.", "그편이 낫습니다. 정말 여러분이 필요한 쪽은 기다립니다. 기다리지 않는 쪽은 아마 다른 걸 찾고 있었던 거고요."),
(G, "Avvocato, Lei che cosa farebbe?", "변호사님이라면 어떻게 하시겠어요?"),
(PM, "Io? Io ho settant'anni e nessuna azienda. Farei quello che faceva Paolo: lascerei che i figli si azzuffassero a tavola, e poi deciderei io.", "저요? 저는 일흔 살에 회사도 없습니다. 파올로가 하던 대로 하겠지요. 자식들이 식탁에서 실컷 다투게 내버려 두고, 그다음에 제가 정하겠습니다."),
(G, "Paolo non lasciava azzuffare nessuno. Usciva in giardino a fumare.", "파올로는 아무도 다투게 내버려 두지 않았어요. 정원에 나가서 담배를 피웠죠."),
(PM, "Appunto. Lasciava che parlassero. E il giardino era la sua decisione.", "바로 그겁니다. 말하게 내버려 둔 거지요. 그리고 정원이 그 사람의 결정이었고요."),
(G, "(ride piano) Il giardino. Me n'ero dimenticata.", "(작게 웃으며) 정원이라. 잊고 있었네요."),

("#", "Scena 3 — Ore 17.30. Il cimitero sulla collina.", "장면 3 — 오후 5시 30분. 언덕 위의 묘지."),
(None, "Il cimitero è piccolo, con i cipressi in fila e la ghiaia che scricchiola sotto le scarpe. Renzo aspetta al cancello, in camicia bianca, con un mazzo di girasoli avvolto nel giornale. Graziella arriva a piedi, con l'ombrello aperto contro il sole.", "묘지는 작고, 사이프러스가 줄지어 서 있으며 자갈이 신발 아래서 사각거린다. 렌초가 흰 셔츠 차림으로 신문지에 싼 해바라기 한 다발을 들고 대문 앞에서 기다린다. 그라치엘라는 햇빛을 가리려고 우산을 펴 들고 걸어서 온다."),
(R, "Signora. Ho preso i girasoli. Il signor Paolo diceva che i fiori da cimitero sono tristi, e i girasoli no.", "사모님. 해바라기를 샀습니다. 파올로 사장님이 묘지 꽃은 슬픈데 해바라기는 안 그렇다고 하셨거든요."),
(G, "Lo diceva anche delle cravatte. Grazie, Renzo. Ma come sapeva che venivo oggi?", "넥타이를 두고도 그런 말을 했지요. 고마워요, 렌초. 그런데 내가 오늘 오는 건 어떻게 알았어요?"),
(R, "Me l'ha detto Giulia. Mi ha scritto: «La nonna va dal nonno. Vacci anche tu, che lei non lo dice ma ci tiene».", "줄리아가 알려 줬어요. '할머니가 할아버지한테 가요. 렌초도 가요. 말은 안 해도 그걸 바라세요'라고 문자를 보냈더군요."),
(G, "Quella bambina scrive più di quanto parla.", "그 애는 말보다 글을 더 많이 해요."),
(R, "Come tutti, alla sua età. Però scrive giusto.", "그 나이엔 다 그렇지요. 그래도 맞는 말을 씁니다."),
(None, "Camminano piano fra le tombe. Davanti alla lapide di Paolo Corsini, Graziella cambia l'acqua al vaso; Renzo toglie due foglie secche con la stessa cura con cui pulisce un bordo.", "두 사람이 무덤 사이를 천천히 걷는다. 파올로 코르시니의 묘비 앞에서 그라치엘라는 꽃병 물을 갈고, 렌초는 가죽 가장자리를 닦을 때와 같은 정성으로 마른 잎 두 장을 걷어 낸다."),
(G, "Renzo, Lei lo sa. Le due lettere.", "렌초, 알고 있지요. 그 편지 두 통."),
(R, "Lo sa tutto il laboratorio, signora. Da noi le notizie passano sotto le porte, come l'aria.", "공방 전체가 압니다, 사모님. 우리 공방에선 소식이 바람처럼 문 밑으로 새거든요."),
(G, "E cosa dice il laboratorio?", "그래서 공방에선 뭐라고 해요?"),
(R, "Il laboratorio è diviso. Le donne della linea della Maison dicono: cinque anni sicuri, finalmente si dorme. I ragazzi della linea Corsini dicono: allora abbiamo lavorato a Ferragosto per niente.", "공방이 갈라졌습니다. 메종 라인 여자들은 '5년 보장이면 드디어 잠 좀 자겠다'고 하고, 코르시니 라인 젊은이들은 '그럼 페라고스토에 괜히 일했네'라고 합니다."),
(G, "E Lei? Lei cosa dice?", "렌초는요? 렌초는 뭐라고 해요?"),
(R, "Io dico che questa scena l'ho già vista. Nel novantasei, quando il signor Ugo e il signor Paolo litigavano per la Maison. E adesso.", "저는 이 장면을 이미 봤다고 합니다. 96년에 우고 사장님과 파올로 사장님이 메종 문제로 다투실 때. 그리고 지금."),
(G, "Nel novantasei Lei era in laboratorio. Io facevo i conti in cucina.", "96년엔 렌초가 공방에 있었죠. 나는 부엌에서 장부를 맞췄고."),
(R, "Ma i muri erano sottili. Il signor Ugo gridava: «Così diventiamo le mani di qualcun altro». Il signor Paolo rispondeva: «Così mangiamo».", "그래도 벽이 얇았지요. 우고 사장님은 '이러면 우리가 남의 손이 된다'고 소리치셨고, 파올로 사장님은 '이러면 먹고산다'고 받으셨습니다."),
(G, "E chi aveva ragione?", "누가 옳았어요?"),
(R, "Tutti e due. Per questo ha vinto chi gridava di meno.", "두 분 다요. 그래서 덜 소리친 분이 이겼지요."),
(G, "Paolo.", "파올로."),
(R, "Il signor Paolo. Ma un anno dopo il signor Ugo è venuto in laboratorio e mi ha detto: «Renzo, non far sparire le borse nostre. Tienine sempre una sul banco». E io l'ho fatto.", "파올로 사장님이요. 그런데 1년 뒤 우고 사장님이 공방에 오셔서 말씀하셨습니다. '렌초, 우리 가방을 없애지 마라. 작업대에 늘 하나는 두어라.' 그래서 저는 그렇게 했습니다."),
(G, "Una borsa sul banco. Per tutti questi anni?", "작업대에 가방 하나. 그 오랜 세월 동안?"),
(R, "Ventinove anni. Una all'anno. Le tengo in un armadio, in fondo al laboratorio. Nessuno me le ha mai chieste.", "29년이요. 1년에 하나씩. 공방 맨 안쪽 장에 넣어 둡니다. 아무도 보여 달라고 한 적이 없지요."),
(G, "Non me l'ha mai detto.", "나한테 한 번도 말한 적 없잖아요."),
(R, "Lei non me l'ha mai chiesto, signora. Da noi si risponde, non si racconta.", "사모님께서 물어보신 적이 없으니까요. 우리 쪽에선 묻는 말에 답하지, 먼저 늘어놓지 않습니다."),
(G, "Renzo... se vendiamo a Parigi, quell'armadio resta chiuso.", "렌초… 파리에 팔면 그 장은 닫힌 채로 남겠네요."),
(R, "Se vendete a Parigi, resta chiuso. Se vendete a Seul, forse si apre. Ma a Seul c'è un altro problema.", "파리에 파시면 닫힌 채로 남습니다. 서울에 파시면 어쩌면 열리겠지요. 하지만 서울엔 다른 문제가 있습니다."),
(G, "Quale?", "뭔데요?"),
(R, "Che si apre lontano. Io ho settantadue anni. Le mie mani a Seul non ci vanno. Ci vanno le borse, e i ragazzi.", "멀리서 열린다는 거지요. 저는 일흔둘입니다. 제 손은 서울에 못 갑니다. 가방이랑 애들이 가지요."),
(G, "Allora non sono i soldi, il problema.", "그럼 문제는 돈이 아니네요."),
(R, "Non sono mai i soldi, signora. Il problema è chi decide quando si spegne la luce in laboratorio. Con il quaranta, la luce la spegne qualcuno a Parigi.", "돈이었던 적은 없습니다, 사모님. 문제는 공방 불을 언제 끌지 누가 정하느냐지요. 40퍼센트면 파리의 누군가가 불을 끕니다."),
(G, "E con il quindici?", "15퍼센트면요?"),
(R, "Con il quindici la spegne ancora la famiglia. Se la famiglia c'è.", "15퍼센트면 여전히 가족이 끕니다. 가족이 있다면 말이지요."),
(None, "Renzo fa due passi indietro, fino al cipresso. Graziella resta sola davanti alla lapide. Parla piano, come al telefono con qualcuno che conosce bene.", "렌초가 사이프러스 쪽으로 두어 걸음 물러난다. 그라치엘라는 묘비 앞에 혼자 남는다. 잘 아는 사람과 통화하듯 낮은 목소리로 말한다."),
(G, "(alla lapide) Paolo. Lo so che non ti piacevano le domande senza risposta. Te la faccio lo stesso. Nel novantasei hai firmato tu. Rifirmeresti?", "(묘비에게) 파올로. 당신이 답 없는 질문을 싫어한 거 알아요. 그래도 할게요. 96년엔 당신이 서명했죠. 다시 서명하겠어요?"),
(None, "Il vento muove i girasoli. Nessuno risponde. Da lontano, Renzo si schiarisce la voce.", "바람이 해바라기를 흔든다. 아무도 대답하지 않는다. 멀리서 렌초가 헛기침을 한다."),
(R, "Signora, mi scusi. Il signor Paolo, l'ultimo inverno, mi ha detto una cosa. Non so se è una risposta.", "사모님, 죄송합니다. 파올로 사장님이 마지막 겨울에 저한테 하신 말씀이 있어요. 그게 답인지는 모르겠지만."),
(G, "Me la dica.", "말해 봐요."),
(R, "Ha detto: «Renzo, io ho dato da mangiare a tutti. Adesso tocca ai miei figli dare da vivere». Allora non l'ho capito bene.", "'렌초, 나는 모두를 먹여 살렸네. 이제 내 자식들이 모두를 살게 할 차례야.' 그땐 잘 이해하지 못했습니다."),
(G, "È la frase di Ugo. Rovesciata.", "우고의 말이네요. 뒤집은 거예요."),
(R, "Rovesciata. Lui faceva così: prendeva le frasi del padre e le girava, come si gira una pelle per guardarne il fiore.", "뒤집은 거지요. 그분은 늘 그랬습니다. 아버지 말을 가져다 뒤집었어요. 가죽 겉면을 보려고 가죽을 뒤집듯이요."),
(G, "Il fiore della pelle. (sorride) Grazie, Renzo.", "가죽의 겉면이라. (미소 지으며) 고마워요, 렌초."),
(R, "Di niente. Vuole che la riaccompagni a casa?", "별말씀을요. 댁까지 모셔다 드릴까요?"),
(G, "No. Mi accompagni giovedì. A cena. Ci saranno tutti.", "아니요. 목요일에 와 줘요. 저녁 식사에. 다들 올 거예요."),
(R, "Giovedì è il giorno del signor Paolo.", "목요일은 파올로 사장님의 날이지요."),
(G, "Appunto. Rimettiamo a tavola anche lui.", "그러니까요. 그 사람도 식탁에 다시 앉히는 거예요."),

("#", "Scena 4 — Ore 21. Il giardino. La chat «Corsini a tavola».", "장면 4 — 밤 9시. 정원. 가족 채팅방 'Corsini a tavola'."),
(None, "Graziella siede sulla panchina del giardino, al buio, nel punto dove Paolo andava a fumare. Giulia le porta un bicchiere d'acqua e il telefono.", "그라치엘라가 어둠 속 정원 벤치에 앉아 있다. 파올로가 담배를 피우러 나오던 바로 그 자리다. 줄리아가 물 한 잔과 휴대폰을 가져다준다."),
(GI, "Nonna, il telefono l'hai chiesto tu. Di domenica sera.", "할머니, 휴대폰 달라고 한 거 할머니야. 일요일 밤에."),
(G, "Lo so. Ogni tanto le regole le rompo io, così vi ricordate chi le ha fatte. Scrivi tu, che io con queste lettere piccole sbaglio.", "알아. 가끔은 내가 규칙을 깨야 너희가 누가 규칙을 만들었는지 기억하지. 네가 써라, 난 이 작은 글자로는 틀린다."),
(GI, "Cosa scrivo?", "뭐라고 써?"),
(G, "Scrivi: «Giovedì, tutti a tavola. Alle otto. Filippo, porta i numeri. Chiara, porta i disegni. Matteo, porta il computer. E portatevi anche voi stessi.»", "이렇게 써라. '목요일, 모두 식탁으로. 8시. 필리포는 숫자를, 키아라는 그림을, 마테오는 컴퓨터를 가져와라. 그리고 너희 자신도 데려와라.'"),
(GI, "«Portatevi anche voi stessi»? È un po' strano.", "'너희 자신도 데려와라'? 좀 이상한데."),
(G, "Lascialo strano. Lo capiranno.", "이상한 대로 둬. 알아들을 거다."),
(None, "Giulia scrive e invia. Dopo pochi secondi il telefono vibra.", "줄리아가 써서 보낸다. 몇 초 뒤 휴대폰이 진동한다."),
(GI, "Lo zio Matteo ha risposto: «Ci sono». La zia Chiara: un cuore. Il babbo... sta scrivendo.", "마테오 삼촌은 '갈게요'. 키아라 고모는 하트 하나. 아빠는… 쓰고 있어."),
(G, "Aspettiamo.", "기다리자."),
(GI, "Ha scritto: «Va bene, mamma. Ma Parigi vuole una risposta entro il quindici».", "이렇게 왔어. '알았어요, 엄마. 근데 파리는 15일까지 답을 달래요.'"),
(G, "Rispondigli: «Parigi può aspettare. Tua madre no».", "답장해라. '파리는 기다릴 수 있어. 네 엄마는 못 기다리고.'"),
(GI, "Nonna! Così si arrabbia.", "할머니! 그러면 아빠 화낼 거야."),
(G, "Si arrabbierà giovedì. Fino a giovedì dorme tranquillo. È questo che fanno le madri, Giulia: spostano la paura di qualche giorno.", "화는 목요일에 내겠지. 목요일까진 편히 잔다. 엄마들이 하는 일이 그거란다, 줄리아. 두려움을 며칠 뒤로 미뤄 주는 거."),
]

